import os, re, json

def load_demo():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    demos = {}
    match = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t)
    for m in match:
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in demos and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            demos[k] = [[int(x) for x in r] for r in rows]
    return demos

